            if value.startswith(("₹", "$")):
                value = value[1:].lstrip()
        elif value.startswith("(") or value.endswith(")"):
            return None

        if not number_pattern.fullmatch(value):
            return None

        amount = float(value.replace(",", ""))
        return -amount if is_debit else amount

    records = []

