def truncate_graphemes(s, n):
    import unicodedata

    clusters = 0
    force_next = False

    for i, char in enumerate(s):
        if i == 0:
            starts_cluster = True
        elif unicodedata.category(char) == "Mn":
            starts_cluster = False
        elif char == "\u200d":
            starts_cluster = False
        elif force_next:
            starts_cluster = False
        else:
            starts_cluster = True

        if starts_cluster:
            clusters += 1
            if clusters > n:
                return s[:i] + "..."

        if char == "\u200d":
            force_next = True
        elif force_next and unicodedata.category(char) != "Mn":
            force_next = False

    return s

