    import unicodedata

    clusters = []
    join_next = False

    for ch in s:
        if unicodedata.category(ch) == "Mn":
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
        elif ch == "\u200d":
            if clusters:
                clusters[-1] += ch
            else:
